script:
html { color-scheme: dark; }
body { background: var(--6aad89d6-6138-430f-b63a-50db36050c49, #101010); }
button { cursor: pointer; }
button:disabled { opacity: 0.4; cursor: not-allowed; }
a, button { transition: opacity 0.15s ease, background 0.15s ease, color 0.15s ease, border-color 0.15s ease; }
a:hover { opacity: 0.65; }
:focus-visible { outline: 2px solid var(--34e3bfcb-2aad-4589-8025-160deff3e9d8, #F2F2F0); outline-offset: 2px; }
[data-shop="variant-option"][data-selected="true"] {
	background: var(--34e3bfcb-2aad-4589-8025-160deff3e9d8, #F2F2F0);
	color: var(--6aad89d6-6138-430f-b63a-50db36050c49, #101010);
	border-color: var(--34e3bfcb-2aad-4589-8025-160deff3e9d8, #F2F2F0);
}
[data-shop="cart-count"][data-empty="true"] { display: none; }
a[data-active="true"] {
	background: var(--ee3565dd-bae0-467b-a486-22eb5eba83f8, #F2F2F0);
	color: var(--6aad89d6-6138-430f-b63a-50db36050c49, #101010);
	border-color: var(--ee3565dd-bae0-467b-a486-22eb5eba83f8, #F2F2F0);
}
input, textarea { font-family: inherit; }
::selection { background: var(--34e3bfcb-2aad-4589-8025-160deff3e9d8, #F2F2F0); color: var(--6aad89d6-6138-430f-b63a-50db36050c49, #101010); }
